cd /workspace/pr/head/.claude; python3 -I -c "
import yaml
c=yaml.safe_load(open('defaults/model-config.yaml'))
for p,v in c['providers'].items():
  for m,e in (v.get('models') or {}).items():
    if 'max_output_tokens' in e: print(p,m,e['max_output_tokens'], e.get('context_window'), e.get('effective_input_ceiling'), e.get('probed_ceiling'))
print(c.get('aliases'))
"; grep -n '"opus"\|\["opus' scripts/generated-model-maps.sh | head

